INSERT INTO "voice_patterns" ("id","rule","pattern","pattern_type","direction","category","before_text","after_text","lesson_text","confidence","enabled") VALUES
('fb76e3ce-a91a-45c6-bca9-8b5685a9310d','No em-dashes in client emails',' — ','literal','avoid','punctuation',NULL,NULL,'Replace em-dashes with periods or commas. Every em-dash in the agent draft was removed: ''response — this is'' became ''response. This is''; ''customers as well — they''re'' became ''customers makes sense, they''re''. Collin does not use em-dashes in client emails. (Confirms lesson 5 — promote from unconfirmed.)','1','true'),
('82135938-e516-47e0-8a7a-f4f5ddb8be1e','Cut closing enthusiasm lines like ''Looking forward to getting started.''','Looking forward to','literal','avoid','style',NULL,NULL,'Don''t summarize or preview what the attached document says. "Here''s the revised proposal as a fixed-price project. It reflects what we discussed: customer and prospect conversations as the primary focus, campaigns and measurement built from real findings, mentoring through doing the work together." was replaced with "I''ve attached the revised proposal to this email." The attachment speaks for itself — point to it, don''t restate its contents. (Confirms lessons 7 and 10.)','1','true'),
('57f9e189-a52a-4677-891c-23746ec2a421','Don''t summarize/preview what the attached document says','It reflects what we discussed','literal','avoid','style',NULL,NULL,'Don''t summarize or preview what the attached document says. "Here''s the revised proposal as a fixed-price project. It reflects what we discussed: customer and prospect conversations as the primary focus, campaigns and measurement built from real findings, mentoring through doing the work together." was replaced with "I''ve attached the revised proposal to this email." The attachment speaks for itself — point to it, don''t restate its contents. (Confirms lessons 7 and 10.)','0.6','true'),
('7be2a8db-7937-4ded-ba64-559a1f5ec14d','Defer scheduling preference to future, accommodate current meeting','( so |, so )(could|can) we (start|move|shift|begin)','regex','avoid','structure',NULL,NULL,NULL,'0.6','true'),
('cec686d0-8fd4-4a3f-b45b-59043236c932','Cut explicit availability confirmation at opener','Yes, I''m available','literal','avoid','style',NULL,NULL,NULL,'0.6','true'),
('9483024d-b4c2-4619-958c-cedec2d8d8d2','Use ''stand-up meeting'' not ''standing meeting''','standing meeting','literal','avoid','factual',NULL,NULL,NULL,'0.6','true'),
('6794524f-18f8-4b68-9d3c-89de5090aae3','Cut email sign-offs on short external messages','^Thanks,','regex','avoid','deletion',NULL,NULL,'Cut email sign-offs like ''Thanks,'' when sending short external messages.','0.6','true'),
('bee33ac8-bc41-445f-ab56-97dec416a1b7','Name the specific action/person instead of vague filler','put something together on my end','literal','avoid','style',NULL,NULL,'Name the specific action and person (''continue with my attorney'') instead of vague filler (''put something together on my end'').','0.6','true'),
('e4199c12-e041-4912-9c08-70476e6ae205','Use present perfect continuous over simple past for ongoing work','I talked through','literal','avoid','style',NULL,NULL,'Use present perfect continuous (''I''ve been talking through'') over simple past (''I talked through'') for ongoing work. More conversational, less formal.','0.6','true'),
('39003433-0ba7-4f4e-a43b-80c80e6d373c','Cut list intro lines and go straight to bullets','They want:','literal','avoid','structure',NULL,NULL,'Cut list intro lines like ''Not token counts. Not skill scores. They want:'' and go straight to the bullet list.','0.6','true'),
('9a6170c3-66d3-45fa-9fb6-d09b1017a753','Cut declarative setup lines before the actual content','That is the gap.','literal','avoid','structure',NULL,NULL,'Cut declarative setup lines like ''That is the gap.'' before the actual content. Just get to the point.','0.6','true'),
('fd92a49f-fd85-48be-b2b3-8e03e32d8033','Replace "not the [noun]" negation framing with a positive qualifier',', not the','literal','avoid','style',NULL,NULL,NULL,'1','true'),
('c1386be4-39b8-4f4b-a20f-73884be0480a','Spell out full causal chain — don''t compress steps with terse shorthand like ''skill leads to''','skill leads to behavior','literal','avoid','style',NULL,NULL,NULL,'0.6','true'),
('c3cd5f2a-7d4a-4ba0-b170-2b8294b699bc','Don''t leave rhetorical questions as standalone open lines. Answer them inline in the same paragraph.','\?\s*$','regex','avoid','structure',NULL,NULL,'Answer rhetorical questions inline (same paragraph) rather than leaving them as standalone open questions. A question mark should be mid-paragraph, followed by the answer, not at the end of a line with the answer in the next paragraph.','0.6','true'),
('eb79ede0-08bc-40c8-a3d1-a63e6df330c6','Don''t use endorsement adjectives when introducing someone','\b(Sharp|sharp|Impressive|impressive|Great candidate|great candidate|Solid|solid),','regex','avoid','deletion',NULL,NULL,NULL,'0.6','true'),
('face86bb-609c-4a13-97c4-0d5cac1f772b','Avoid pitching a friend''s qualities in intro messages','does the homework|highly recommend|you''d (really )?enjoy|you''d love','regex','avoid','deletion',NULL,NULL,NULL,'0.6','true'),
('8f557576-fdd3-48e6-b631-e18643f846b8','Don''t use endorsement clichés to describe someone — let facts speak','does the homework','literal','avoid','style','Sharp, client-facing, does the homework.','(deleted entirely)','Don''t pitch a friend''s qualities, school, or credentials when making an intro. State their situation factually (''interested in transitioning to a customer-facing role'') and let the recipient decide.','0.6','true'),
('16473d17-b1fe-4454-b4a6-088df6ef27b9','Don''t use ''on your radar'' in intros — state the situation directly','on your radar','literal','avoid','style','Wanted to put a close friend on your radar.','I have a friend interested in transitioning to a customer-facing role...','Don''t pitch a friend''s qualities, school, or credentials when making an intro. State their situation factually (''interested in transitioning to a customer-facing role'') and let the recipient decide.','0.6','true'),
('f4570f3d-68cf-4c88-b46d-89d3c7e7af93','Use a casual idiom like ''long time no talk'' instead of ''great reconnecting''','great reconnecting','literal','avoid','style','Hey [Name], great reconnecting. We talked a couple months back...','Hey [Name], long time no talk. I''m loving the new [Company] website tho!','Open LinkedIn DMs with a casual idiom like ''long time no talk'' plus a specific compliment about their recent work, not a recap of when/how you last met. They remember.','0.6','true'),
('dfa9f1ce-c431-46c3-b19b-8d92113e1804','Don''t tell the recipient what they''d enjoy — let them decide','I think you''d enjoy','literal','avoid','style','I think you''d enjoy a quick chat with him.','I thought a conversation could be useful for you both to meet.','Don''t pitch a friend''s qualities, school, or credentials when making an intro. State their situation factually (''interested in transitioning to a customer-facing role'') and let the recipient decide.','0.6','true'),
('55d18a40-9410-4118-a2d8-e9075ac53b32','Don''t front-load the LinkedIn link at the start of a line — offer to send it instead (''happy to send over his LinkedIn'')','^Here''s .+ (LinkedIn|linkedin)','regex','avoid','structure','Here''s his LinkedIn if you''re open to it: [link].','happy to send over his Linkedin so you guys can chat.','Offer to share the person''s LinkedIn rather than front-loading the link. Make the ask a soft opt-in (''happy to send over his LinkedIn'') so the recipient raises their hand first.','0.6','true'),
('a3a8878b-9cb4-40bf-a8fd-31f2ee8539db','Soften imperatives to suggestions in team emails','^(Record|No pitching|Aim for|Lead with|Hold the|Do not mention)\b','regex','avoid','style',NULL,NULL,NULL,'0.6','true'),
('ac18c9a2-5a23-4f45-bd7e-6fb374f20d39','Don''t present strategy as fact — frame as opinion','^(Here is what is actually|This is what is actually|GenCon is a|X is a discovery)','regex','avoid','style',NULL,NULL,NULL,'0.6','true'),
('8b8d5c4e-772b-4471-8de7-a51a7b352d44','Cut dramatic metaphors and hard sales targets from team instructions','(kill for|opens doors|worth more than.*\$|oh shit moment|Aim for \d+)','regex','avoid','style',NULL,NULL,NULL,'1','true'),
('ff164e88-3874-4291-b88e-d9b3bf2e8a7a','No bare prohibitions without a recovery path','^(Do not|No pitching|Never)\b','regex','avoid','structure',NULL,NULL,NULL,'0.6','true'),
('37d40777-99a1-49de-94fe-e29608422e67','Don''t name your product/tool in customer-facing scripts','ImportYeti','literal','avoid','style',NULL,NULL,NULL,'1','true'),
('2ca44a9f-ad9d-4e49-b7eb-d6276d1f3dd5','No commanding section headers in team emails','(A few rules|Here are the rules|Rules for)','regex','avoid','structure',NULL,NULL,NULL,'0.6','true'),
('2115c7ca-6477-4e9e-b364-d561c941b551','Soften imperative bullets to "Try to" suggestions when mentoring a team','^- Record everything','regex','avoid','style','Record everything. Phone in pocket, app on. Customer language is our marketing copy.','Try to record everything with your phone in a front pocket and voice memos.','Soften imperative commands to "try to" suggestions when writing to a team you''re mentoring. Agent wrote "Record everything. Phone in pocket, app on." and "No pitching." and "Aim for 20-plus real conversations." Collin changed all three to "Try to record everything," "Try not to pitch," "Try to log as much as you can." Mentor emails suggest and guide. They don''t issue orders.','0.6','true'),
('76c72eed-86e6-45ef-a7b4-caf77275f020','Soften hard prohibitions to "Try not to" when mentoring a team','^- No pitching','regex','avoid','style','No pitching. If they ask what you do, you are students researching this.','Try not to pitch. If they ask what you do, you are students researching this.','Soften imperative commands to "try to" suggestions when writing to a team you''re mentoring. Agent wrote "Record everything. Phone in pocket, app on." and "No pitching." and "Aim for 20-plus real conversations." Collin changed all three to "Try to record everything," "Try not to pitch," "Try to log as much as you can." Mentor emails suggest and guide. They don''t issue orders.','0.6','true'),
('d1531191-8279-4f22-8560-1be2f214ce14','Cut marketing/copywriting framing from internal mentoring emails — the team are students, not a marketing department','marketing copy','literal','avoid','deletion','Customer language is our marketing copy.',NULL,'Cut marketing and sales metaphors from internal mentoring emails. "Customer language is our marketing copy" was deleted entirely. "Leverage most salespeople would kill for" became "some insane leverage." "Worth more than a handful of $399 sales" was deleted. The team are students learning a process, not a marketing department. Keep it grounded in what they are doing, not in copywriting theory or sales dramatization.','0.6','true'),
('2dce6d6e-3bfb-4991-b5ff-853d73be98f8','Frame advice as opinion ("my opinion on what could be worth trying") not as fact when mentoring','Here is what is actually worth doing','literal','avoid','style','Here is what is actually worth doing.','Here is my opinion on what could be worth trying.','Frame advice as your opinion, not as fact, when writing to a team you''re mentoring. "GenCon is a discovery trip" became "In my opinion, GenCon is a discovery trip." "Here is what is actually worth doing" became "Here is my opinion on what could be worth trying." Collin positions his recommendations as his take, leaving the team room to think for themselves rather than issuing directives.','0.6','true'),
('cb596c3b-8a6b-4688-8726-64fda4701cec','Cut dramatic sales metaphors ("would kill for") from internal mentoring emails — use plain enthusiasm ("some insane leverage")','salespeople would kill for','literal','avoid','style','that is leverage most salespeople would kill for','that is some insane leverage, people are much more willing to respond to students','Cut marketing and sales metaphors from internal mentoring emails. "Customer language is our marketing copy" was deleted entirely. "Leverage most salespeople would kill for" became "some insane leverage." "Worth more than a handful of $399 sales" was deleted. The team are students learning a process, not a marketing department. Keep it grounded in what they are doing, not in copywriting theory or sales dramatization.','0.6','true'),
('06a3f95f-485c-49b0-970c-11c8efd3ca4d','Don''t open sections with negative result stats','sent roughly.*with zero|with zero real responses|with zero responses','regex','avoid','structure',NULL,NULL,NULL,'0.6','true'),
('3cce4ca4-495b-4497-9e0e-6c51dd934340','Don''t demand access or prescribe specific migrations in follow-ups','Please send me access to .* so I can dig in','literal','avoid','style',NULL,NULL,NULL,'0.6','true'),
('81ff1c3e-5bae-4805-b47b-6b7598e27564','Prefer open-ended closing over task-specific help offer','if anything''s unclear or if you need help','literal','avoid','style',NULL,NULL,NULL,'0.6','true'),
('33e08778-4218-44c4-bfc2-c4178a594e8e','Don''t frame action item lists with directive headers like "Here''s what to change"','Here''s what to change:','literal','avoid','structure',NULL,NULL,NULL,'0.6','true'),
('cfc60c6d-fbf8-4476-b62a-64cd5eecdc22','Use collaborative recap framing like "Here''s what we discussed" for action item lists','Here''s what we discussed:','literal','prefer','structure',NULL,NULL,NULL,'0.6','true'),
('b27acc80-c782-4c61-b921-d50cc3d85827','Cut confirmed/known logistics from follow-up emails — if it was decided in the meeting, restating adds noise','is confirmed\.','regex','avoid','structure',NULL,NULL,'Cut confirmed/known logistics from follow-up emails (''Friday meeting is confirmed, Parker''s out'') — if it was decided in the meeting, restating it adds noise','0.6','true'),
('0bf72126-b878-4e7c-ba00-7f8da58fe60c','Use a specific grade level (''3rd grade reading level'') not a vague qualifier (''low reading level'')','(low|high) reading level','regex','avoid','style',NULL,NULL,'Use concrete metrics (''3rd grade reading level'') over vague qualifiers (''low reading level'') — specific numbers are more actionable than descriptors','0.6','true'),
('f6b7e763-3cfc-4487-890f-96a72e894fc7','Frame action items as shared (''that we talked about'') not assigned (''on your side'') in mentoring follow-ups','on your side','literal','avoid','style',NULL,NULL,'Frame follow-up action items as shared discussion (''what we discussed'', ''that we talked about'') not as directives (''what to change'', ''on your side'') — collaborative framing in mentoring follow-ups','0.6','true'),
('33310985-6ff5-4a01-a728-179d36270a34','Use past tense (''I sent over'') for actions already completed — don''t promise a future send if it''s already done','I''m sending over','literal','avoid','style',NULL,NULL,'Report completed actions (''I sent over'', ''I invited to the repo'') not future promises (''I''m sending over'', ''I''m sending a tool'') in follow-up emails — if it''s already done, say it''s done','0.6','true'),
('9a1c0e53-bc18-475f-935f-6a13a844bf04','Use collaborative framing (''what we discussed'') not directive (''what to change'') in mentoring follow-ups','what to change','literal','avoid','style',NULL,NULL,'Frame follow-up action items as shared discussion (''what we discussed'', ''that we talked about'') not as directives (''what to change'', ''on your side'') — collaborative framing in mentoring follow-ups','0.6','true'),
('f5bbd909-1d27-4435-be83-a4bba5d3a17b','Soften absolute claims to possibilities (''can get flagged'') and add supporting evidence','\bgets? flagged\b','regex','avoid','style',NULL,NULL,'Soften absolute claims to possibilities (''can get flagged'' over ''gets flagged'') and add supporting evidence (''when you sent manually you got replies'') instead of stating the mechanism alone','0.6','true'),
('b0be6ca1-efaf-4a44-b4a6-4366b2840fe3','Cut the ''not grading you'' reassurance hedge — state the practical reason you''re asking instead','not grading you','literal','avoid','style','I''m sizing the timeline to your actual bandwidth, not grading you on it.','but a range would be helpful for planning.','Drop reassurance hedges that explain your question is benign; state the practical reason instead. ''I''m sizing the timeline to your actual bandwidth, not grading you on it'' became ''but a range would be helpful for planning.'' The ''not grading you'' reassurance is noise; the reason you''re asking (''helpful for planning'') is the signal. Don''t over-explain that a question is harmless — just say why you need the answer.','0.6','true'),
('e652a110-fbf4-4e76-9fb2-77e6ae9d1da4','Cut heavy motivational/communication-pressure closes in short check-ins — end light and open instead','Going quiet is the only thing that actually costs us','literal','avoid','structure','The goal we''re all pointing at is simple... Going quiet is the only thing that actually costs us.','Feel free to reach out with ideas, questions, thoughts, I''m all ears.','Keep short check-in closings light and open; cut the heavy goal/communication-pressure paragraph. Deleted the whole ''The goal we''re all pointing at is simple... Going quiet is the only thing that actually costs us.'' close and replaced it with ''Feel free to reach out with ideas, questions, thoughts, I''m all ears.'' Short check-ins end on a warm, open invitation, not a motivational paragraph or a guilt-trip about staying in the loop.','0.6','true'),
('faa20c52-c047-41cf-81ed-56fb105388a0','Don''t open a check-in close with grand goal framing — keep the close light and open','The goal we''re all pointing at','literal','avoid','structure',NULL,NULL,'Keep short check-in closings light and open; cut the heavy goal/communication-pressure paragraph. Deleted the whole ''The goal we''re all pointing at is simple... Going quiet is the only thing that actually costs us.'' close and replaced it with ''Feel free to reach out with ideas, questions, thoughts, I''m all ears.'' Short check-ins end on a warm, open invitation, not a motivational paragraph or a guilt-trip about staying in the loop.','0.6','true'),
('7acaceae-0e6e-4ec5-8ab4-00ee6f5c9ad1','Don''t frame a team-ask list as ''I need from everyone'' — reframe as a collaborative two-way ask (soften imperatives to ''Try and'', add a reciprocal commitment of what you''ll do)','I need from everyone','literal','avoid','structure','Three things I need from everyone so we can move, then I''m out of your hair:','to make this go a little smoother, I think it would be helpful to grow as a team for us to:','Reframe team requirements as a collaborative two-way ask, not a directive list. ''Three things I need from everyone so we can move'' became ''to make this go a little smoother, I think it would be helpful to grow as a team for us to:'' — softer, with an ''I think'' hedge, framed as team growth. Then for each ask: soften the imperative (''Try and check CDL email'' over ''Check email once a day'') AND add a reciprocal commitment (''I''ll send out email notices a day early''). This embodies ''I don''t want to be their boss'' — make every demand a two-way street.','0.6','true'),
('149bdc7d-0d59-48f6-9405-61b31709743d','Don''t open sentences with ''Moreover,'' — it''s empty connective padding','Moreover, ','literal','avoid','structure',NULL,NULL,'Cut filler transition words like ''Moreover'' that open a sentence without adding content — they signal AI-generated padding and delay the actual claim.','0.6','true'),
('7d006dc3-6f3a-4d71-9269-d60e65898b30','Cut the buzzword adjective ''cutting-edge'' — describe what the thing actually does','cutting-edge','literal','avoid','wording',NULL,NULL,'Replace stacked corporate buzzwords (cutting-edge, seamlessly, leverage) with plain, concrete verbs and nouns — one plain sentence beats a buzzword chain.','0.6','true'),
('2703b46e-0db1-4724-95ce-f3ee124ef2d8','Cut the buzzword adverb ''seamlessly'' — let the mechanism imply smoothness','seamlessly ','literal','avoid','wording',NULL,NULL,'Replace stacked corporate buzzwords (cutting-edge, seamlessly, leverage) with plain, concrete verbs and nouns — one plain sentence beats a buzzword chain.','0.6','true'),
('e9fe5dc7-ccc1-4a51-879d-629831180deb','Replace the verb ''leverage'' with a concrete action verb like ''use'' or ''turns into''','leverage','literal','avoid','wording',NULL,NULL,'Replace stacked corporate buzzwords (cutting-edge, seamlessly, leverage) with plain, concrete verbs and nouns — one plain sentence beats a buzzword chain.','0.6','true'),
('6ade6a0a-8f93-4305-a994-e323707692be','Cut vague value-abstraction phrases like ''deliver value'' — state the concrete outcome instead','deliver value','literal','avoid','wording',NULL,NULL,'Replace vague abstraction (''leverage our learnings to deliver value'') with a concrete subject-verb-object statement of what turns into what (''turns our notes into better products'') — name the input, the mechanism, and the output.','0.6','true'),
('a1599c1f-bbd5-4fa8-b715-3c8a703833d2','Prefer concrete transformation phrasing like ''turns our notes into'' over abstract processing language','turns our notes into','literal','prefer','wording',NULL,NULL,'Replace vague abstraction (''leverage our learnings to deliver value'') with a concrete subject-verb-object statement of what turns into what (''turns our notes into better products'') — name the input, the mechanism, and the output.','0.6','true'),
('02725f10-704c-440e-8791-1102ea3fd019','Don''t use the jargon noun ''learnings'' — name the concrete artifact (notes, docs, data)','learnings','literal','avoid','wording',NULL,NULL,'Replace corporate jargon nouns like ''learnings'' with the concrete thing they refer to — the human swapped ''our learnings'' for ''our notes'', naming the actual artifact.','0.6','true'),
('5270923c-e997-4c17-a768-cdf3926848be','State product capability in present tense, not ''platform will <verb>''','platform will','literal','avoid','tone',NULL,NULL,'Describe what a product does in present tense (''turns our notes into''), not future tense — the human cut ''will'' from the platform description, making the claim direct instead of promissory.','0.6','true'),
('b00b52e8-9646-4872-9578-4b57004e510b','Avoid codename+version doc titles; title should describe the outcome','PoC v2','literal','avoid','structure',NULL,NULL,'Don''t title documents with internal codenames plus version numbers (''G-Brain PoC v2'') — the human retitled to a plain sentence stating what the platform does, so the title carries information instead of an internal label.','0.6','true'),
('839427bf-d823-4864-87c4-0a4d798e1789','No em-dashes in client emails',' — ','literal','avoid','punctuation',NULL,NULL,'Replace em-dashes with periods or commas. Every em-dash in the agent draft was removed: ''response — this is'' became ''response. This is''; ''customers as well — they''re'' became ''customers makes sense, they''re''. Collin does not use em-dashes in client emails. (Confirms lesson 5 — promote from unconfirmed.)','1','true'),
('7bcbc7f1-35af-4f97-b484-ad12cf7b0721','Cut closing enthusiasm lines like ''Looking forward to getting started.''','Looking forward to','literal','avoid','style',NULL,NULL,'Don''t summarize or preview what the attached document says. "Here''s the revised proposal as a fixed-price project. It reflects what we discussed: customer and prospect conversations as the primary focus, campaigns and measurement built from real findings, mentoring through doing the work together." was replaced with "I''ve attached the revised proposal to this email." The attachment speaks for itself — point to it, don''t restate its contents. (Confirms lessons 7 and 10.)','1','true'),
('be7d544d-9fe6-4f72-83e2-8f7bed17f52a','Don''t summarize/preview what the attached document says','It reflects what we discussed','literal','avoid','style',NULL,NULL,'Don''t summarize or preview what the attached document says. "Here''s the revised proposal as a fixed-price project. It reflects what we discussed: customer and prospect conversations as the primary focus, campaigns and measurement built from real findings, mentoring through doing the work together." was replaced with "I''ve attached the revised proposal to this email." The attachment speaks for itself — point to it, don''t restate its contents. (Confirms lessons 7 and 10.)','0.6','true'),
('1aa1e5a3-d5b1-4f4a-bba4-fbccd809e137','Defer scheduling preference to future, accommodate current meeting','( so |, so )(could|can) we (start|move|shift|begin)','regex','avoid','structure',NULL,NULL,NULL,'0.6','true'),
('a34c3fd0-64ce-4bab-ba8c-f799c3989216','Cut explicit availability confirmation at opener','Yes, I''m available','literal','avoid','style',NULL,NULL,NULL,'0.6','true'),
('762eeae8-be96-49de-85b7-e4e9e6c9033a','Use ''stand-up meeting'' not ''standing meeting''','standing meeting','literal','avoid','factual',NULL,NULL,NULL,'0.6','true');
